"""Native aggregate boundary metadata, separate from clean source polylines."""
from . import curved_port_bindings


def compile(snapshot, plan, label, *, origin=(0.,0.,0.)):
    result=curved_port_bindings.compile(snapshot,plan,label,origin=origin,endpoint_ownership=True)
    rows=[p for site in plan.sites for p in site.ports]
    if len(rows)!=len(plan.designs):raise ValueError('Missing aggregate mouth design')
    mesh=result.ports.copy();mesh.name=label+' aggregate mouth incidences'
    fields=[('st_cj_order','INT',[i for site in plan.sites for i in range(len(site.ports))])]
    for key,source in (('street_id','street_id'),('section_id','section_id'),('junction_id','junction_id'),
                       ('connector_id','connector_id'),('reverse','reverse'),('span_index','span')):
        fields.append(('st_cj_'+key,'INT',[v.value for v in result.ports.attributes['st_pp_'+source].data]))
    for key in ('radius','rise','datum','half','bundle_id','partner','bridge'):
        prefix='st_ag_' if key in ('partner','bridge') else 'st_cj_'
        kind='BOOLEAN' if key=='bridge' else 'INT' if key in ('half','bundle_id','partner') else 'FLOAT'
        fields.append((prefix+key,kind,[getattr(d,key) for d in plan.designs]))
    for name,kind,values in fields:
        mesh.attributes.new(name,kind,'POINT').data.foreach_set('value',values)
    return result,mesh
